-- Hauptmigration: bestanden im Blindlöser.
-- LSA-Aufgaben taschenrechnersicher (30.10.2026, vor Batus LSA am 31.10.). Standard: docs/aufgaben/tr-sichere-items.md,
-- Einzelnachweis: docs/aufgaben/tr-umbau-2026-10-30.md.
--
-- Nur Daten, 4 freigegebene LSA-Aufgaben: Aus dem Endwert (NUMERIC) wird ein Lückentext (MULTI_PART, nur Zahlenfelder,
-- weil das Tablet Zahl, Bruch und ax+b kennt, kein √). ID, Skill, Thema, Klasse, AFB, einsatz bleiben.
-- Je Aufgabe nur, wo der Vorher-Stand steht (status ready, NUMERIC, alter Aufgabentext); ein zweiter Lauf und der
-- CI-Neuaufbau (Aufgaben fehlen) treffen 0 Zeilen.
--
-- Status 'review': In Prüfliste und Admin-Reihe „zur Freigabe“. Keine Aufgabe wird hier freigegeben. Vor dem Umbau wird die
-- Ausgangsfassung gesichert, damit die Änderung als „geändert“ erscheint: pruef_freigabe_erlaubt ist dann false, Themen-
-- und Sammelfreigabe lassen die Aufgabe aus, Rasit gibt jede einzeln frei (pruef_admin_freigeben). Der Trigger
-- tasks_hinweise_bei_ruecknahme setzt vorhandene Hinweise auf entwurf; die Freigabe setzt sie wieder auf geprueft.
-- Gate-Prüfung am Ende: Besteht eine Aufgabe freigabe_gate_fehler nicht, bricht die Migration ab.
-- Kein begin/commit: mig klammert. Rollback: supabase/rollback/20261030084254_lsa_tr_sichere_binom.sql

do $tr$
declare
  r record;
  v_alt_status text;
  v_n integer;
  v_ges integer := 0;
  v_gate text;
begin
  for r in
    select * from jsonb_to_recordset($alle$[
{"id": "88ca2551-82bf-4ca3-b971-32cd4292a146", "alt_question": "Berechne geschickt mit einer binomischen Formel.\n\n47² - 43² = ?", "question": "Berechne geschickt mit einer binomischen Formel. Fülle dazu die Lücken aus.\n\n47² - 43² = (☐ + ☐) · (☐ - ☐) = ☐ · ☐ = ☐", "title": "Faktorisieren · geschicktes Rechnen · 47² - 43²", "est": 120, "parts": [{"nr": 1, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Erste Zahl in der Plus-Klammer", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 2, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zweite Zahl in der Plus-Klammer", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 3, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Erste Zahl in der Minus-Klammer", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 4, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zweite Zahl in der Minus-Klammer", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 5, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Erster Faktor", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 6, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zweiter Faktor", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 7, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Ergebnis", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}], "correct_answers": {"1": ["47", "+47", "43", "+43"], "2": ["43", "+43", "47", "+47"], "3": ["47", "+47"], "4": ["43", "+43"], "5": ["90", "+90", "4", "+4"], "6": ["4", "+4", "90", "+90"], "7": ["360", "+360"]}, "acceptance": {"1": {"canonical": "47", "equivalents": ["+47", "43", "+43"]}, "2": {"canonical": "43", "equivalents": ["+43", "47", "+47"]}, "3": {"canonical": "47", "equivalents": ["+47"]}, "4": {"canonical": "43", "equivalents": ["+43"]}, "5": {"canonical": "90", "equivalents": ["+90", "4", "+4"]}, "6": {"canonical": "4", "equivalents": ["+4", "90", "+90"], "known_errors": {"-4": "betrag_fehler"}}, "7": {"canonical": "360", "equivalents": ["+360"], "known_errors": {"16": "quadrat_gliedweise", "+16": "quadrat_gliedweise", "-360": "betrag_fehler"}}}, "solution": "47² - 43² = (47 + 43) · (47 - 43) = 90 · 4 = 360.\nIn der Plus-Klammer und beim Produkt ist die Reihenfolge egal, in der Minus-Klammer nicht.", "typical_errors": [{"error": "47² - 43² wird als (47 - 43)² gerechnet: 16.", "fehlbild": "quadrat_gliedweise", "socratic_question": "Ist 47² - 43² dasselbe wie (47 - 43)²? Probiere es mit kleinen Zahlen wie 3² - 2² aus."}, {"error": "Nur (47 + 43) = 90 wird berechnet, der Faktor (47 - 43) = 4 fehlt.", "fehlbild": "90", "socratic_question": "Aus wie vielen Faktoren besteht (a + b)(a - b)?"}]},
{"id": "7e027634-1c45-4c70-8357-198dad0f1797", "alt_question": "Berechne geschickt mit einer binomischen Formel.\n\n102 · 98 = ?", "question": "Berechne geschickt mit einer binomischen Formel. Fülle dazu die Lücken aus.\n\n102 · 98 = (100 + ☐) · (100 - ☐) = ☐ - ☐ = ☐", "title": "Dritte binomische Formel · geschicktes Rechnen · 102 · 98", "est": 90, "parts": [{"nr": 1, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl in der Plus-Klammer", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 2, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl in der Minus-Klammer", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 3, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl vor dem Minus", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 4, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl nach dem Minus", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 5, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Ergebnis", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}], "correct_answers": {"1": ["2", "+2"], "2": ["2", "+2"], "3": ["10000", "+10000"], "4": ["4", "+4"], "5": ["9996", "+9996"]}, "acceptance": {"1": {"canonical": "2", "equivalents": ["+2"]}, "2": {"canonical": "2", "equivalents": ["+2"]}, "3": {"canonical": "10000", "equivalents": ["+10000"]}, "4": {"canonical": "4", "equivalents": ["+4"]}, "5": {"canonical": "9996", "equivalents": ["+9996"], "known_errors": {"10004": "quadratdifferenz_vorzeichen", "+10004": "quadratdifferenz_vorzeichen"}}}, "solution": "102 · 98 = (100 + 2) · (100 - 2) = 10000 - 4 = 9996.", "typical_errors": [{"error": "Das Vorzeichen von b² wird falsch gesetzt: 100² + 2² = 10004.", "fehlbild": "quadratdifferenz_vorzeichen", "socratic_question": "Ist 102 · 98 größer oder kleiner als 100 · 100?"}]},
{"id": "3b1e6f0a-5c2d-4e8b-9f71-2a6d0c4b8e13", "alt_question": "Berechne geschickt mit Hilfe einer binomischen Formel.\n\n49² = ?", "question": "Berechne geschickt mit Hilfe einer binomischen Formel. Fülle dazu die Lücken aus.\n\n49² = (50 - ☐)² = ☐ - ☐ + ☐ = ☐", "title": "Zweite binomische Formel · geschicktes Rechnen · 49²", "est": 90, "parts": [{"nr": 1, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl in der Klammer", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 2, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Erstes Glied", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 3, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Mittleres Glied", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 4, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Letztes Glied", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 5, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Ergebnis", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}], "correct_answers": {"1": ["1", "+1"], "2": ["2500", "+2500"], "3": ["100", "+100"], "4": ["1", "+1"], "5": ["2401", "+2401"]}, "acceptance": {"1": {"canonical": "1", "equivalents": ["+1"]}, "2": {"canonical": "2500", "equivalents": ["+2500"]}, "3": {"canonical": "100", "equivalents": ["+100"], "known_errors": {"50": "mal_zwei_vergessen", "+50": "mal_zwei_vergessen", "0": "quadrat_gliedweise", "+0": "quadrat_gliedweise"}}, "4": {"canonical": "1", "equivalents": ["+1"]}, "5": {"canonical": "2401", "equivalents": ["+2401"], "known_errors": {"2399": "vorzeichen_potenz", "+2399": "vorzeichen_potenz", "2451": "mal_zwei_vergessen", "+2451": "mal_zwei_vergessen", "2499": "quadrat_gliedweise", "+2499": "quadrat_gliedweise", "2501": "quadrat_gliedweise", "+2501": "quadrat_gliedweise", "2601": "binom_formel_verwechselt", "+2601": "binom_formel_verwechselt"}}}, "solution": "49² = (50 - 1)² = 2500 - 100 + 1 = 2401.", "typical_errors": [{"error": "Gliedweise quadriert, das Mischglied fehlt: 50² - 1² = 2499.", "fehlbild": "quadrat_gliedweise", "socratic_question": "Ist (50 - 1)² dasselbe wie 50² - 1²? Probiere es mit (3 - 1)² aus."}, {"error": "Gliedweise quadriert, das Mischglied fehlt: 50² + 1² = 2501.", "fehlbild": "quadrat_gliedweise", "socratic_question": "Ist (50 - 1)² dasselbe wie 50² + 1²? Probiere es mit (3 - 1)² aus."}, {"error": "Mischglied ohne Faktor 2: 2500 - 50 + 1 = 2451.", "fehlbild": "mal_zwei_vergessen", "socratic_question": "Wie heißt das mittlere Glied in (a - b)² = a² - … + b²?"}, {"error": "Das letzte Glied mit Minus: 2500 - 100 - 1 = 2399.", "fehlbild": "vorzeichen_potenz", "socratic_question": "Kann ein Quadrat wie (-1)² negativ sein?"}, {"error": "Erste statt zweiter Formel: 2500 + 100 + 1 = 2601.", "fehlbild": "binom_formel_verwechselt", "socratic_question": "Ist 49² größer oder kleiner als 50²?"}]},
{"id": "8c4a2d71-0e9b-4f36-b5a8-6d1f3e7c9a24", "alt_question": "Vereinfache den Term zuerst anhand der binomischen Formeln und setze dann für x den Wert 100 ein.\n\n(x + 5)² - (x + 2)(x - 2) = ?", "question": "Vereinfache den Term zuerst anhand der binomischen Formeln und setze dann für x den Wert 100 ein. Fülle dazu die Lücken aus.\n\n(x + 5)² - (x + 2)(x - 2)\n\n(x + 5)² = x² + ☐x + ☐\n(x + 2)(x - 2) = x² - ☐\nZusammengefasst: ☐x + ☐\nFür x = 100: ☐", "title": "Binomische Formeln gemischt · vereinfachen und einsetzen · x = 100", "est": 120, "parts": [{"nr": 1, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl vor dem x bei (x + 5)²", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 2, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl ohne x bei (x + 5)²", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 3, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl nach dem Minus bei (x + 2)(x - 2)", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 4, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zusammengefasst: Zahl vor dem x", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 5, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zusammengefasst: Zahl ohne x", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}, {"nr": 6, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Wert für x = 100", "competency_content": "arithmetik_algebra", "competency_process": "Problemlösen, Operieren"}], "correct_answers": {"1": ["10", "+10"], "2": ["25", "+25"], "3": ["4", "+4"], "4": ["10", "+10"], "5": ["29", "+29"], "6": ["1029", "+1029"]}, "acceptance": {"1": {"canonical": "10", "equivalents": ["+10"], "known_errors": {"5": "mal_zwei_vergessen", "+5": "mal_zwei_vergessen", "0": "quadrat_gliedweise", "+0": "quadrat_gliedweise"}}, "2": {"canonical": "25", "equivalents": ["+25"], "known_errors": {"10": "qf_quadrat_als_verdopplung", "+10": "qf_quadrat_als_verdopplung"}}, "3": {"canonical": "4", "equivalents": ["+4"]}, "4": {"canonical": "10", "equivalents": ["+10"]}, "5": {"canonical": "29", "equivalents": ["+29"], "known_errors": {"21": "quadratdifferenz_vorzeichen", "+21": "quadratdifferenz_vorzeichen"}}, "6": {"canonical": "1029", "equivalents": ["+1029"], "known_errors": {"29": "quadrat_gliedweise", "+29": "quadrat_gliedweise", "1021": "quadratdifferenz_vorzeichen", "+1021": "quadratdifferenz_vorzeichen", "21021": "vorzeichen_ignoriert", "+21021": "vorzeichen_ignoriert"}}}, "solution": "(x + 5)² = x² + 10x + 25\n(x + 2)(x - 2) = x² - 4\nx² + 10x + 25 - (x² - 4) = 10x + 29\nFür x = 100: 10 · 100 + 29 = 1029.", "typical_errors": [{"error": "Die Klammer x² - 4 mit falschem Vorzeichen abgezogen: 10x + 21, also 1021.", "fehlbild": "quadratdifferenz_vorzeichen", "socratic_question": "Was ergibt -(x² - 4), wenn du die Klammer auflöst?"}, {"error": "Gliedweise quadriert: (x + 5)² = x² + 25, übrig bleibt 29.", "fehlbild": "quadrat_gliedweise", "socratic_question": "Ist (x + 5)² dasselbe wie x² + 25? Setze x = 1 ein und vergleiche."}, {"error": "Das Minus vor dem zweiten Produkt weggelassen: 2x² + 10x + 21, also 21021.", "fehlbild": "vorzeichen_ignoriert", "socratic_question": "Welches Rechenzeichen steht zwischen den beiden Produkten?"}]}
]$alle$::jsonb) as x(id uuid, alt_question text, question text, title text, est integer, parts jsonb,
                     correct_answers jsonb, acceptance jsonb, solution text, typical_errors jsonb)
  loop
    if not exists (select 1 from public.tasks t where t.id = r.id and t.status = 'ready' and t.input_type = 'NUMERIC'
                      and t.question = r.alt_question) then
      raise notice 'tr: % nicht im Vorher-Stand, übersprungen', r.id;
      continue;
    end if;
    perform public.pruef_ausgang_sichern(r.id);
    update public.tasks
       set question = r.question, question_payload = null, input_type = 'MULTI_PART', parts = r.parts,
           title = r.title, est_duration_sec = r.est, status = 'review', reviewed_by = null, reviewed_at = null
     where id = r.id and status = 'ready';
    get diagnostics v_n = row_count;
    update public.task_solutions
       set correct_answers = r.correct_answers, acceptance = r.acceptance, solution = r.solution,
           typical_errors = r.typical_errors, updated_at = now()
     where task_id = r.id;
    v_ges := v_ges + v_n;
    v_gate := public.freigabe_gate_fehler(r.id);
    if v_gate is not null then
      raise exception 'tr: % besteht das Gate nicht: %', r.id, v_gate;
    end if;
  end loop;
  raise notice 'tr: % Aufgabe(n) umgebaut', v_ges;
end
$tr$;
